package foodordering;
import java.time.*;import java.util.*;
public final class Order { public static final double TAX_RATE=.05; private final String code,customer,phone,orderType,payment; private final Map<FoodItem,Integer> items; private final double subtotal,tax,total; private final LocalDateTime createdAt;
 public Order(String customer,String phone,String type,String payment,Cart cart){if(customer==null||customer.isBlank())throw new IllegalArgumentException("Customer name is required.");if(cart==null||cart.isEmpty())throw new IllegalArgumentException("Cart is empty.");code="FD"+LocalDate.now().toString().replace("-","")+"-"+UUID.randomUUID().toString().substring(0,5).toUpperCase();this.customer=customer.trim();this.phone=phone==null?"":phone.trim();orderType=type;this.payment=payment;items=new LinkedHashMap<>(cart.getItems());subtotal=cart.calculateSubtotal();tax=subtotal*TAX_RATE;total=subtotal+tax;createdAt=LocalDateTime.now();}
 public String getCode(){return code;}public String getCustomer(){return customer;}public String getPhone(){return phone;}public String getOrderType(){return orderType;}public String getPayment(){return payment;}public Map<FoodItem,Integer> getItems(){return Collections.unmodifiableMap(items);}public double getSubtotal(){return subtotal;}public double getTax(){return tax;}public double getTotal(){return total;}public LocalDateTime getCreatedAt(){return createdAt;}
}
